input = __import__('sys').stdin.readline
n = int(input())
a = list(map(int, input().split())) + [n + 1]
cache = {}

def check(i, u, d):
	keys = []
	j = i
	while j + 1 <= n:
		key = (j, u, d)
		v = cache.get(key, -1)
		if v != -1:
			j = v
			break
		keys.append(key)
		if u < a[j] < d:
			if a[j] < a[j + 1]:
				u = max(u, a[j])
			elif a[j] > a[j + 1]:
				d = min(d, a[j])
		elif u < a[j]:
			u = a[j]
		elif d > a[j]:
			d = a[j]
		else:
			break
		j += 1
	for key in keys:
		cache[key] = j
	return j
ans = 0
for i in range(n):
	u = 0
	d = n + 1
	j = check(i, u, d)
	ans += j - i
print(ans)
